DIRECTIONS <- list(c(1L,0L),c(-1L,0L),c(0L,1L),c(0L,-1L),c(1L,1L),c(-1L,-1L),c(-1L,1L),c(1L,-1L))
path_costs <- function(base,left,width,height,direction,p1,p2,gamma) {
  rx <- direction[1L]
  ry <- direction[2L]
  rows <- if (ry >= 0L) 0:(height-1L) else (height-1L):0
  columns <- if (rx >= 0L) 0:(width-1L) else (width-1L):0
  result <- matrix(0,nrow(base),ncol(base))
  for (y in rows) for (x in columns) {
    p <- y*width+x+1L
    qx <- x-rx
    qy <- y-ry
    if (!(qx >= 0L && qx < width && qy >= 0L && qy < height)) {
      result[p,] <- base[p,]
      next
    }
    q <- qy*width+qx+1L
    previous <- result[q,]
    smallest <- min(previous)
    penalty <- max(p1,(p2*gamma) %/% (gamma+abs(left[p]-left[q])))
    for (d in seq_len(ncol(base))) {
      best <- min(previous[d],smallest+penalty)
      if (d > 1L) best <- min(best,previous[d-1L]+p1)
      if (d < ncol(base)) best <- min(best,previous[d+1L]+p1)
      result[p,d] <- base[p,d]+best-smallest
    }
  }
  result
}
cumulative_costs <- function(base,left,width,height,paths,p1,p2,gamma) {
  total <- matrix(0,nrow(base),ncol(base))
  result <- list()
  for (direction in DIRECTIONS[seq_len(paths)]) {
    total <- total+path_costs(base,left,width,height,direction,p1,p2,gamma)
    result[[length(result)+1L]] <- total
  }
  result
}

clamped <- function(image,width,height,x,y) image[min(max(y,0L),height-1L)*width+min(max(x,0L),width-1L)+1L]
box_sum <- function(image,width,height,window) {
  radius <- window %/% 2
  padded_width <- width+2*radius
  padded_height <- height+2*radius
  integral <- matrix(0,padded_height+1L,padded_width+1L)
  for (y in 0:(padded_height-1L)) {
    row_sum <- 0
    for (x in 0:(padded_width-1L)) {
      row_sum <- row_sum+clamped(image,width,height,x-radius,y-radius)
      integral[y+2L,x+2L] <- integral[y+1L,x+2L]+row_sum
    }
  }
  result <- numeric(width*height)
  for (y in 0:(height-1L)) for (x in 0:(width-1L)) result[y*width+x+1L] <- integral[
      y+window+1L,
      x+window+1L
  ]-integral[y+1L,x+window+1L]-integral[y+window+1L,x+1L]+integral[y+1L,x+1L]
  result
}
census <- function(image,width,height) {
  result <- integer(width*height)
  for (y in 0:(height-1L)) for (x in 0:(width-1L)) {
    code <- 0L
    center <- image[y*width+x+1L]
    for (dy in -2:2) for (dx in -2:2) {
      if (dx == 0L && dy == 0L) next
      code <- 2L*code+as.integer(clamped(image,width,height,x+dx,y+dy) < center)
    }
    result[y*width+x+1L] <- code
  }
  result
}
texture <- function(image,width,height,window) {
  gradient <- numeric(width*height)
  for (y in 0:(height-1L)) for (x in 0:(width-1L)) gradient[y*width+x+1L] <- abs(clamped(image,width,height,x+1L,y)-clamped(
      image,
      width,
      height,
      x-1L,
      y
  ))
  box_sum(gradient,width,height,window)
}
popcount <- function(value) {
  count <- 0L
  while (value != 0L) {
    count <- count+value %% 2L
    value <- value %/% 2L
  }
  count
}
cost_volume <- function(left,right,cl,cr,width,height,kind,window,dmin,dmax) {
  volume <- matrix(0,length(left),dmax-dmin+1L)
  for (d in dmin:dmax) {
    pixels <- numeric(length(left))
    for (y in 0:(height-1L)) for (x in 0:(width-1L)) {
      p <- y*width+x+1L
      q <- y*width+max(x-d,0L)+1L
      difference <- left[p]-right[q]
      pixels[p] <- if (kind == "census") popcount(bitwXor(
          cl[p],
          cr[q]
      )) else if (kind == "sad") abs(difference) else difference*difference
    }
    volume[,d-dmin+1L] <- box_sum(pixels,width,height,window)
  }
  volume
}

REGION_ORDER <- c("nonocc","all","disc")
truth_regions <- function(truth,width,height) {
  known <- which(truth != 0)
  occluded <- integer()
  for (p in known) {
    y <- (p-1L) %/% width
    x <- (p-1L) %% width
    g <- truth[p]
    target <- x-g
    row <- truth[seq.int(y*width+1L,(y+1L)*width)]
    if (target < 0 || any(row > g & 0:(width-1L)-row == target)) occluded <- c(occluded,p)
  }
  visible <- setdiff(known,occluded)
  disc <- integer()
  for (p in visible) {
    y <- (p-1L) %/% width
    x <- (p-1L) %% width
    adjacent <- integer()
    for (yy in max(0L,y-1L):min(height-1L,y+1L)) for (xx in max(0L,x-1L):min(width-1L,x+1L)) adjacent <- c(
        adjacent,
        yy*width+xx+1L
    )
    if (any(truth[adjacent] != 0 & abs(truth[adjacent]-truth[p]) >= 2)) disc <- c(disc,p)
  }
  list(all=known,nonocc=visible,disc=disc,occluded=occluded)
}
evaluate <- function(image,truth,region) {
  valid_pixels <- region[image[region] != 0]
  errors <- abs(image[valid_pixels]-truth[valid_pixels])
  valid <- length(errors)
  missing <- length(region)-valid
  total <- sum(errors)
  list(
      pixels=length(region),
      valid=valid,
      bad1=missing+sum(errors > 1),
      bad2=missing+sum(errors > 2),
      error_sum=total,
      mae=if (valid) two_decimals(total,valid) else "-",
      exact=sum(errors == 0)
  )
}
integer_gcd <- function(a,b) {
  while (b != 0) {
    remainder <- a %% b
    a <- b
    b <- remainder
  }
  a
}
ratio <- function(a,b) {
  if (b == 0) return("0/1 0.00")
  divisor <- integer_gcd(a,b)
  paste0(integer_text(a %/% divisor),"/",integer_text(b %/% divisor)," ",two_decimals(100*a,b))
}

integer_text <- function(value) sprintf("%.0f",value)
read_pgm <- function(path) {
  lines <- readLines(path)
  dimensions <- as.integer(strsplit(lines[2L]," ",fixed=TRUE)[[1L]])
  list(
      width=dimensions[1L],
      height=dimensions[2L],
      pixels=as.numeric(unlist(strsplit(lines[-(1:3)]," ",fixed=TRUE)))
  )
}
read_parameters <- function() {
  params <- list(sample_pixels=list())
  for (line in readLines("input/params.txt")) {
    words <- strsplit(line," ",fixed=TRUE)[[1L]]
    name <- words[1L]
    if (name == "sample") params$sample_pixels[[length(params$sample_pixels)+1L]] <- as.integer(words[2:3]) else if (name %in% c(
        "wta_cost",
        "sgm_cost"
    )) params[[name]] <- words[2L] else if (endsWith(name,"_windows")) params[[name]] <- as.integer(words[-1L]) else params[[name]] <- as.numeric(words[2L])
  }
  params
}
write_pgm <- function(path,width,height,pixels) {
  lines <- c("P2",paste(width,height),"255")
  for (y in 0:(height-1L)) lines <- c(
      lines,
      paste(integer_text(pixels[seq.int(y*width+1L,(y+1L)*width)]),collapse=" ")
  )
  writeLines(lines,path,useBytes=TRUE)
}
